const body = $json.body || {};

// 1. Discord PING
if (body.type === 1) {
  return { response_body: { type: 1 }, should_resume: false, should_open_slack_modal: false, is_caterflow: false, is_lumina: false };
}

// 2. Discord Button Click (type: 3) -> Return Modal definition (type: 9)
if (body.type === 3) {
  const custom_id = body.data?.custom_id || '';
  return {
    response_body: {
      type: 9,
      data: {
        title: 'Incident Sign-Off',
        custom_id: 'd_m|' + custom_id,
        components: [
          {
            type: 1,
            components: [
              {
                type: 4,
                custom_id: 'approver_notes',
                label: 'Resolution Notes / Verification',
                style: 2,
                min_length: 3,
                max_length: 1000,
                placeholder: 'Enter verification details before dispatching to client...',
                required: true
              }
            ]
          }
        ]
      }
    },
    should_resume: false,
    should_open_slack_modal: false,
    is_caterflow: false,
    is_lumina: false
  };
}

// 3. Discord Modal Submit (type: 5)
if (body.type === 5) {
  const raw_custom_id = body.data?.custom_id || '';
  const parts = raw_custom_id.split('|');
  const action = (parts[1] === 'escl' || parts[1] === 'escalated') ? 'escalated' : 'approved';
  const raw_token = parts[2] ? decodeURIComponent(parts[2]) : '';
  const approver = body.member?.user?.username || body.user?.username || 'Discord User';
  const notes = body.data?.components?.[0]?.components?.[0]?.value || 'Direct sign-off';

  let baseResume = raw_token;
  if (baseResume && !baseResume.startsWith('http')) {
    baseResume = 'https://YOUR-N8N-HOST/webhook-waiting/' + baseResume;
  }

  const sep = baseResume.includes('?') ? '&' : '?';
  const resume_url = baseResume + sep + 'decision=' + action + '&platform=discord&approver=@' + encodeURIComponent(approver) + '&notes=' + encodeURIComponent(notes);

  return {
    response_body: { type: 6 },
    should_resume: !!baseResume,
    should_open_slack_modal: false,
    is_caterflow: false,
    is_lumina: false,
    resume_url: resume_url
  };
}

// 4. Slack Interactivity
if (body.payload) {
  let p = body.payload;
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) {}
  }

  // Slack Button Click
  if (p && p.type === 'block_actions') {
    const actionObj = p.actions?.[0] || {};
    const actionVal = actionObj.value || actionObj.action_id || '';

    // Check if this is an ENT-02 CaterFlow Lead action!
    if (actionVal.startsWith('caterflow_')) {
      const parts = actionVal.split('|');
      const caterflow_action = (actionObj.action_id === 'caterflow_intro' || parts[0] === 'caterflow_intro') ? 'intro' : 'approve';
      const reply_id = parts[1] || '';
      const approver = p.user?.username || p.user?.name || 'Laurence';

      return {
        source: 'slack_caterflow_button',
        is_caterflow: true,
        is_lumina: false,
        caterflow_action: caterflow_action,
        reply_id: reply_id,
        response_url: p.response_url,
        user_name: approver,
        response_body: { ok: true },
        should_open_slack_modal: false,
        should_resume: false
      };
    }

    // Check if this is an ENT-03 Lumina Goods action!
    if (actionVal.startsWith('lumina_')) {
      const parts = actionVal.split('|');
      const actionType = parts[0] || 'lumina_refund_full';
      const ticketId = parts[1] || '';
      const orderNumber = parts[2] || '';
      const amount = parts[3] || '0';
      const approver = p.user?.username || p.user?.name || 'Laurence';

      return {
        source: 'slack_lumina_button',
        is_lumina: true,
        is_caterflow: false,
        lumina_action: actionType,
        ticket_id: ticketId,
        order_number: orderNumber,
        amount: amount,
        response_url: p.response_url,
        user_name: approver,
        response_body: { ok: true },
        should_open_slack_modal: false,
        should_resume: false
      };
    }

    return {
      source: 'slack_button',
      trigger_id: p.trigger_id,
      private_metadata: actionVal,
      response_body: { ok: true },
      should_open_slack_modal: true,
      should_resume: false,
      is_caterflow: false,
      is_lumina: false
    };
  }

  // Slack Modal Submit -> Resume main workflow
  if (p && p.type === 'view_submission') {
    const metadata = p.view?.private_metadata || '';
    const parts = metadata.split('|');
    const decision = parts[0] || 'approved';
    const raw_resume = parts[1] ? decodeURIComponent(parts[1]) : '';
    const approver = p.user?.username || p.user?.name || 'Slack User';
    const notes = p.view?.state?.values?.notes_block?.notes_input?.value || 'Direct sign-off';
    const sep = raw_resume.includes('?') ? '&' : '?';
    const resume_url = raw_resume + sep + 'decision=' + decision + '&platform=slack&approver=@' + encodeURIComponent(approver) + '&notes=' + encodeURIComponent(notes);

    return {
      source: 'slack_modal_submit',
      response_body: { response_action: 'clear' },
      should_open_slack_modal: false,
      should_resume: !!raw_resume,
      is_caterflow: false,
      is_lumina: false,
      resume_url: resume_url
    };
  }
}

return { response_body: { ok: true }, should_resume: false, should_open_slack_modal: false, is_caterflow: false, is_lumina: false };

